<script setup>
import { ref, onMounted, computed } from 'vue';
import { api } from '../../services/api.js';
import { workspace } from '../../services/workspace.js';
import { auth, canFeature } from '../../services/auth.js';
import { money,statuses } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
import DataTable from '../../components/DataTable.vue';
import DashboardCharts from '../../components/DashboardCharts.vue';
const data=ref(null),error=ref(''),loading=ref(true),plan=ref(null);const store=computed(()=>workspace.stores.find(s=>s._id===workspace.activeStoreId));
onMounted(async()=>{try{if(workspace.activeStoreId){[data.value,plan.value]=await Promise.all([api.get(`/stores/${workspace.activeStoreId}/dashboard`),api.get('/me/plan')]);}}catch(e){error.value=e.message}finally{loading.value=false}});
const columns=[{key:'number',label:'Pedido'},{key:'customer.name',label:'Cliente'},{key:'total',label:'Total'},{key:'status',label:'Estado'}];
</script>
<template><div><header class="p-page-header"><div><p class="p-eyebrow">CADA PASO CUENTA</p><h1>Hola, {{auth.user?.name?.split(' ')[0]||'emprendedor'}} <span style="color:#5da492">✦</span></h1><p>Así viene {{store?.name||'tu negocio'}}. Tu próximo gran día empieza acá.</p></div><div class="p-page-header-actions"><RouterLink v-if="canFeature('section.design')" to="/app/design" class="btn btn-secondary"><Icon name="palette" :size="16"/>Personalizar tienda</RouterLink><RouterLink v-if="canFeature('section.products')" to="/app/products/new" class="btn btn-primary"><Icon name="plus" :size="16"/>Agregar producto</RouterLink></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="!store" class="p-empty-page"><Icon name="store" :size="42"/><h2>Tu tienda está por comenzar</h2><p>Contactá a la administración para que te asigne una tienda y puedas cargar tus productos.</p><RouterLink to="/app/subscription" class="btn btn-primary">Ver mi suscripción</RouterLink></div><div v-else-if="loading" class="p-loading-page"><span class="p-spinner"/>Cargando tu negocio...</div><template v-else-if="data"><div v-if="plan?.entitlement&&!plan.entitlement.allowed" class="p-info p-warning"><strong>Tu plan terminó.</strong> Podés seguir editando todos tus productos. Contactanos para volver a publicar y recibir pedidos. <RouterLink to="/app/subscription">Ver mi suscripción →</RouterLink></div><div v-else-if="plan?.entitlement?.trial" class="p-info"><strong>Estás en período de prueba.</strong> Aprovechá estos días para dejar tu tienda lista para vender. <RouterLink to="/app/subscription">Ver detalle →</RouterLink></div><div class="p-stats"><article v-for="s in [{label:'Ingresos totales',value:money(data.revenue),icon:'chart',note:`${data.unitsSold||0} unidades vendidas`},{label:'Pedidos pagados',value:data.paidOrders,icon:'receipt',note:`${data.pendingOrders||0} pedidos por resolver`},{label:'Productos',value:data.products,icon:'package',note:'En el catálogo de tu tienda'},{label:'Stock bajo',value:Array.isArray(data.lowStock)?data.lowStock.length:data.lowStock,icon:'stock',note:'Productos para reponer'}]" :key="s.label" class="p-stat"><span class="p-stat-icon"><Icon :name="s.icon" :size="17"/></span><span class="p-stat-label">{{s.label}}</span><strong class="p-stat-value">{{s.value??0}}</strong><small class="p-stat-note">{{s.note}}</small></article></div><div class="p-dashboard-grid"><DashboardCharts :series="data.salesSeries" :revenue="data.revenue"/><section class="p-section-card"><div class="p-section-title"><div><h2>Hacé que tu tienda brille</h2><p>Pequeños pasos, grandes resultados</p></div><Icon name="sparkles" :size="18"/></div><div class="p-checklist"><RouterLink v-if="canFeature('section.products')" to="/app/products/new"><span><Icon name="package" :size="18"/></span><span><strong>Cargá tus productos</strong><small>Fotos que cuenten su historia</small></span><Icon name="chevron" :size="14"/></RouterLink><RouterLink v-if="canFeature('section.design')" to="/app/design"><span><Icon name="palette" :size="18"/></span><span><strong>Dale tu identidad</strong><small>Colores, portada y experiencia</small></span><Icon name="chevron" :size="14"/></RouterLink><RouterLink v-if="canFeature('section.payments')" to="/app/payments"><span><Icon name="credit" :size="18"/></span><span><strong>Elegí cómo cobrar y entregar</strong><small>Una compra fácil de principio a fin</small></span><Icon name="chevron" :size="14"/></RouterLink></div></section></div><div v-if="canFeature('section.orders')" class="p-section-title"><div><h2>Pedidos recientes</h2><p>Seguí cada compra de cerca</p></div><RouterLink to="/app/orders" class="btn btn-text">Ver todos <Icon name="arrow" :size="14"/></RouterLink></div><DataTable v-if="canFeature('section.orders')" :rows="data.recentOrders||[]" :columns="columns" :searchable="false" :limit="5" empty-text="Tu primera venta se va a ver acá."><template #cell-total="{value}"><strong>{{money(value)}}</strong></template><template #cell-status="{value}"><span class="p-badge" :class="value">{{statuses[value]||value}}</span></template><template #actions="{row}"><RouterLink :to="`/app/orders/${row._id}`" class="p-icon-btn" title="Ver pedido"><Icon name="eye" :size="15"/></RouterLink></template></DataTable><section v-if="data.topProducts?.length" class="p-section-card p-top-products"><div class="p-section-title"><div><h2>Los más vendidos</h2><p>Productos que tus clientes vuelven a elegir</p></div></div><div v-for="(product,i) in data.topProducts" :key="product._id" class="p-activity-item"><span>{{i+1}}</span><div style="flex:1"><strong>{{product.name}}</strong><small>{{product.quantity}} unidades vendidas</small></div><strong>{{money(product.total)}}</strong></div></section></template></div></template>
